import test from 'node:test';import assert from 'node:assert/strict';import {DatabaseSync} from 'node:sqlite';import {readFileSync} from 'node:fs';import ts from 'typescript';
const source=ts.transpileModule(readFileSync('worker/skyline-billing.ts','utf8'),{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ES2022}}).outputText;
const {skylineBilling,skylineDeletionMaintenance}=await import('data:text/javascript;base64,'+Buffer.from(source).toString('base64'));
const keys=await crypto.subtle.generateKey({name:'RSASSA-PKCS1-v1_5',modulusLength:2048,publicExponent:new Uint8Array([1,0,1]),hash:'SHA-256'},true,['sign','verify']);
const pem='-----BEGIN PRIVATE KEY-----\n'+Buffer.from(await crypto.subtle.exportKey('pkcs8',keys.privateKey)).toString('base64')+'\n-----END PRIVATE KEY-----';
function setup(){let failBatchAt=-1;const sql=new DatabaseSync(':memory:');sql.exec(readFileSync('drizzle/0003_skyline_billing.sql','utf8'));sql.exec(readFileSync('drizzle/0004_skyline_coin_shop.sql','utf8'));sql.exec(readFileSync('drizzle/0005_skyline_refunds.sql','utf8'));sql.exec(readFileSync('drizzle/0006_skyline_partial_refunds.sql','utf8'));sql.exec(readFileSync('drizzle/0008_skyline_deletion_requests.sql','utf8'));sql.exec(readFileSync('drizzle/0009_skyline_deletion_completion.sql','utf8'));sql.exec(readFileSync('drizzle/0010_skyline_deletion_health.sql','utf8'));sql.exec(readFileSync('drizzle/0011_skyline_production_billing.sql','utf8'));const db={prepare(q){let values=[];return {bind(...args){values=args;return this},async first(){return sql.prepare(q).get(...values)??null},async all(){return {results:sql.prepare(q).all(...values)}},execute(){return /^SELECT\b/i.test(q)?{results:sql.prepare(q).all(...values),meta:{changes:0}}:{results:[],meta:{changes:sql.prepare(q).run(...values).changes}}},async run(){return this.execute()}}},async batch(statements){sql.exec('BEGIN');try{const out=[];for(let i=0;i<statements.length;i++){if(i===failBatchAt){failBatchAt=-1;throw new Error("injected_batch_failure");}out.push(statements[i].execute())};sql.exec('COMMIT');return out}catch(e){sql.exec('ROLLBACK');throw e}}};return {sql,failBatchAt(index){failBatchAt=index},env:{DB:db,SKYLINE_PAYMENTS_ENABLED:'sandbox',GOOGLE_PLAY_SERVICE_ACCOUNT_EMAIL:'test@example.invalid',GOOGLE_PLAY_SERVICE_ACCOUNT_PRIVATE_KEY:pem}}}
function request(path,body,session){return new Request('https://example.invalid/api/skyline/'+path,{method:body===undefined?'GET':'POST',headers:{...(session?{Authorization:'Bearer '+session}:{}),'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)})}
async function account(env){return (await skylineBilling(request('account',{}),env)).json()}
function purchase(member,product='skyline_coins_1500'){return {obfuscatedExternalAccountId:member,testPurchaseContext:{fopType:'TEST'},purchaseStateContext:{purchaseState:'PURCHASED'},acknowledgementState:'ACKNOWLEDGEMENT_STATE_PENDING',productLineItem:[{productId:product,productOfferDetails:{quantity:1,refundableQuantity:1,consumptionState:'CONSUMPTION_STATE_YET_TO_BE_CONSUMED'}}]}}
function google(p,failAck=false){return async(url)=>String(url).includes('oauth2')?Response.json({access_token:'fixture'}):String(url).includes('productsv2')?Response.json(p):new Response(null,{status:failAck?503:204})}
async function verify(env,a,p,token='fixture-token',fail=false){const response=await skylineBilling(request('verify',{productId:p.productLineItem[0].productId,purchaseToken:token},a.sessionToken),env,google(p,fail));return {response,data:await response.json()}}
test('server-created credentials hashed, recovery rotates and invalidates old session',async()=>{const {env,sql}=setup(),a=await account(env);assert.match(a.sessionToken,/^[a-f0-9]{64}$/);assert.notEqual(sql.prepare('SELECT session_hash FROM skyline_members').get().session_hash,a.sessionToken);const r=await skylineBilling(request('recover',{memberId:a.memberId,recoveryToken:a.recoveryToken}),env);assert.equal(r.status,200);assert.equal((await skylineBilling(request('entitlements',undefined,a.sessionToken),env)).status,401);assert.equal((await skylineBilling(request('recover',{memberId:a.memberId,recoveryToken:a.recoveryToken}),env)).status,401)});
test('missing auth and disabled server cannot grant',async()=>{const {env}=setup(),a=await account(env);assert.equal((await skylineBilling(request('verify',{}),env)).status,401);env.SKYLINE_PAYMENTS_ENABLED=undefined;assert.equal((await verify(env,a,purchase(a.memberId))).response.status,503)});
test('pending and cancelled purchases grant nothing',async()=>{for(const state of ['PENDING','CANCELLED']){const {env}=setup(),a=await account(env),p=purchase(a.memberId);p.purchaseStateContext.purchaseState=state;const r=await verify(env,a,p);assert.equal(r.data.wallet?.coins??0,0);assert.equal(r.response.status,state==='PENDING'?200:409)}});
test('wrong account, non-test, refunded quantity and product mismatch rejected',async()=>{for(const mutation of [p=>p.obfuscatedExternalAccountId='other',p=>delete p.testPurchaseContext,p=>p.productLineItem[0].productOfferDetails.refundableQuantity=0,p=>p.productLineItem.push(p.productLineItem[0])]){const {env}=setup(),a=await account(env),p=purchase(a.memberId);mutation(p);assert.notEqual((await verify(env,a,p)).response.status,200)}});
