test('founder bundle once, durable gadgets spend with replay and overspend protection',async()=>{const {env}=setup(),a=await account(env),p=purchase(a.memberId,'skyline_founder_bundle');let r=await verify(env,a,p);assert.deepEqual(r.data.entitlements,['founder']);assert.deepEqual(r.data.wallet,{coins:1500,net:3,smoke:3});assert.equal((await verify(env,a,p,'different-token')).response.status,409);for(let i=0;i<3;i++){const id='spend-request-000'+i;const res=await skylineBilling(request('spend',{item:'net',requestId:id},a.sessionToken),env);assert.equal(res.status,200);assert.equal((await skylineBilling(request('spend',{item:'net',requestId:id},a.sessionToken),env)).status,200)}assert.equal((await skylineBilling(request('spend',{item:'net',requestId:'spend-request-9999'},a.sessionToken),env)).status,409)});
