test('paid coins buy fixed catalogue gadgets once and return authoritative balances',async()=>{const {env}=setup(),a=await account(env);await verify(env,a,purchase(a.memberId));const body={item:'net',requestId:'coin-buy-request-0001'};let res=await skylineBilling(request('buy',body,a.sessionToken),env);assert.equal(res.status,200);assert.deepEqual((await res.json()).wallet,{coins:1300,net:1,smoke:0});res=await skylineBilling(request('buy',body,a.sessionToken),env);assert.deepEqual((await res.json()).wallet,{coins:1300,net:1,smoke:0});res=await skylineBilling(request('buy',{item:'smoke',requestId:'coin-buy-request-0002'},a.sessionToken),env);assert.deepEqual((await res.json()).wallet,{coins:1150,net:1,smoke:1});assert.equal((await skylineBilling(request('buy',{item:'smoke',requestId:body.requestId},a.sessionToken),env)).status,409)});
test('concurrent paid coin buys cannot overdraw and concurrent identical id grants once',async()=>{const {env,sql}=setup(),a=await account(env);await verify(env,a,purchase(a.memberId));let answers=await Promise.all(Array.from({length:5},()=>skylineBilling(request('buy',{item:'net',requestId:'repeated-coin-buy-0001'},a.sessionToken),env)));assert.equal(answers.filter(r=>r.status===200).length,5);assert.deepEqual(sql.prepare('SELECT coins,net,smoke FROM skyline_wallets').get(),Object.assign(Object.create(null),{coins:1300,net:1,smoke:0}));answers=await Promise.all(Array.from({length:10},(_,i)=>skylineBilling(request('buy',{item:'net',requestId:'unique-coin-buy-000'+i},a.sessionToken),env)));assert.equal(answers.filter(r=>r.status===200).length,6);assert.equal(sql.prepare('SELECT coins FROM skyline_wallets').get().coins,100);assert.equal(sql.prepare('SELECT net FROM skyline_wallets').get().net,7)});
test('client prices quantities unknown items and unauthenticated buys rejected',async()=>{const {env}=setup(),a=await account(env);await verify(env,a,purchase(a.memberId));for(const body of [{item:'net',price:1},{item:'net',quantity:100},{item:'__proto__'},{item:'revive'},{item:'net',cost:0}])assert.equal((await skylineBilling(request('buy',{...body,requestId:'wrong-price-buy-0001'},a.sessionToken),env)).status,400);assert.equal((await skylineBilling(request('buy',{item:'net',requestId:'anonymous-buy-0001'}),env)).status,401);const res=await skylineBilling(request('entitlements',undefined,a.sessionToken),env);assert.deepEqual((await res.json()).wallet,{coins:1500,net:0,smoke:0})});
test('sandbox economy remains closed when server flag disabled',async()=>{const {env}=setup(),a=await account(env);await verify(env,a,purchase(a.memberId,'skyline_founder_bundle'));env.SKYLINE_PAYMENTS_ENABLED=undefined;for(const path of ['buy','spend'])assert.equal((await skylineBilling(request(path,{item:'net',requestId:'closed-economy-0001'},a.sessionToken),env)).status,503);const res=await skylineBilling(request('entitlements',undefined,a.sessionToken),env);assert.deepEqual((await res.json()).wallet,{coins:1500,net:3,smoke:3})});
test('hosting runner can execute every semicolon-split pending migration independently',()=>{const db=new DatabaseSync(':memory:');for(const name of ['0003_skyline_billing.sql','0004_skyline_coin_shop.sql','0005_skyline_refunds.sql','0006_skyline_partial_refunds.sql']){const source=readFileSync('drizzle/'+name,'utf8');assert.doesNotMatch(source,/CREATE TRIGGER/i);for(const statement of source.split(';').map(s=>s.replace(/^--.*$/gm,'').trim()).filter(Boolean))db.prepare(statement).run()}assert.equal(db.prepare("SELECT count(*) n FROM sqlite_master WHERE type='trigger'").get().n,0);assert.ok(db.prepare("SELECT name FROM sqlite_master WHERE name='skyline_coin_buys_v2'").get());db.close()});
test('purchase batch failure rolls back admitted token and all inventory; retry grants once',async()=>{for(const index of [1,2,3]){const state=setup(),a=await account(state.env),p=purchase(a.memberId,'skyline_founder_bundle');state.failBatchAt(index);assert.equal((await verify(state.env,a,p)).response.status,503);assert.equal(state.sql.prepare('SELECT count(*) n FROM skyline_purchases_v2').get().n,0);assert.equal(state.sql.prepare('SELECT coins FROM skyline_wallets').get().coins,0);const result=await verify(state.env,a,p);assert.equal(result.data.wallet.coins,1500);assert.equal(result.data.wallet.net,3);assert.deepEqual(result.data.entitlements,['founder'])}});
