test('local D1 runtime runs split migrations and atomic billing under concurrency',{skip:process.env.SKYLINE_TEST_D1!=='1'},async()=>{const {Miniflare}=await import('miniflare');const mf=new Miniflare({modules:true,script:'export default {fetch(){return new Response("local")}}',d1Databases:{DB:'skyline-local-test'},compatibilityDate:'2026-05-22'});try{const db=await mf.getD1Database('DB');for(const name of ['0003_skyline_billing.sql','0004_skyline_coin_shop.sql','0005_skyline_refunds.sql','0006_skyline_partial_refunds.sql'])for(const statement of readFileSync('drizzle/'+name,'utf8').split(';').map(s=>s.replace(/^--.*$/gm,'').trim()).filter(Boolean))await db.prepare(statement).run();const env={DB:db,SKYLINE_PAYMENTS_ENABLED:'sandbox',GOOGLE_PLAY_SERVICE_ACCOUNT_EMAIL:'test@example.invalid',GOOGLE_PLAY_SERVICE_ACCOUNT_PRIVATE_KEY:pem},a=await account(env),p=purchase(a.memberId);const verified=await Promise.all(Array.from({length:4},()=>verify(env,a,p)));assert.ok(verified.every(r=>r.response.status===200));let wallet=await db.prepare('SELECT coins,net,smoke FROM skyline_wallets').first();assert.equal(wallet.coins,1500);const buys=await Promise.all(Array.from({length:10},(_,i)=>skylineBilling(request('buy',{item:'net',requestId:'d1-concurrent-buy-'+i},a.sessionToken),env)));assert.equal(buys.filter(r=>r.status===200).length,7);wallet=await db.prepare('SELECT coins,net,smoke FROM skyline_wallets').first();assert.equal(wallet.coins,100);assert.equal(wallet.net,7);const uses=await Promise.all(Array.from({length:10},(_,i)=>skylineBilling(request('spend',{item:'net',requestId:'d1-concurrent-use-'+i},a.sessionToken),env)));assert.equal(uses.filter(r=>r.status===200).length,7);assert.equal((await db.prepare('SELECT net FROM skyline_wallets').first()).net,0);const refunds=await Promise.all(Array.from({length:3},()=>reconcileRefunds(env,['fixture-token'])));assert.equal(refunds.reduce((n,r)=>n+r.data.revoked,0),1);assert.equal((await db.prepare('SELECT coins FROM skyline_wallets').first()).coins,0);assert.equal((await db.prepare('SELECT coins_debt FROM skyline_refunds').first()).coins_debt,1400);assert.equal((await verify(env,a,p)).response.status,409)}finally{await mf.dispose()}});
const ownerKey='fixture-owner-secret-0001';
async function reconcileRefunds(env,tokens,{partial,remaining,at=Date.now()-1000,fail=false,pages=false,invalid=false}={}){env.OWNER_KEY_HASH=Buffer.from(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(ownerKey))).toString('hex');let calls=0;const send=async url=>{if(String(url).includes('oauth2'))return Response.json({access_token:'fixture'});if(String(url).includes('productsv2')){const token=decodeURIComponent(String(url).split('/').at(-1)),tokenHash=Buffer.from(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token))).toString('hex'),p=await env.DB.prepare('SELECT member,product,quantity FROM '+(env.SKYLINE_BILLING_ENVIRONMENT==='production'?'skyline_production_purchases_v2':'skyline_purchases_v2')+' WHERE token_hash=?').bind(tokenHash).first();const proof=purchase(p.member,p.product);if(env.SKYLINE_BILLING_ENVIRONMENT==='production')delete proof.testPurchaseContext;proof.productLineItem[0].productOfferDetails.quantity=p.quantity;proof.productLineItem[0].productOfferDetails.refundableQuantity=remaining??p.quantity-partial;if(invalid)proof.obfuscatedExternalAccountId='wrong';return Response.json(proof)}calls++;if(fail)return new Response(null,{status:503});assert.match(String(url),/includeQuantityBasedPartialRefund=true/);return Response.json({voidedPurchases:tokens.map(token=>({purchaseToken:token,voidedTimeMillis:String(at),...(partial?{voidedQuantity:partial}:{})})),...(pages?{tokenPagination:{nextPageToken:'opaque-next-page'}}:{})})};const response=await skylineBilling(request('reconcile',{},ownerKey),env,send);return {response,data:await response.json(),calls}}
test('refund revoke and replay deduct once; permanent suit revoked and token cannot regrant',async()=>{const {env,sql}=setup(),a=await account(env),p=purchase(a.memberId,'skyline_founder_bundle');await verify(env,a,p);let r=await reconcileRefunds(env,['fixture-token']);assert.equal(r.data.revoked,1);r=await reconcileRefunds(env,['fixture-token']);assert.equal(r.data.revoked,0);assert.equal(sql.prepare('SELECT settlement FROM skyline_purchases_v2').get().settlement,'revoked');const snapshot=await(await skylineBilling(request('entitlements',undefined,a.sessionToken),env)).json();assert.deepEqual(snapshot.entitlements,[]);assert.deepEqual(snapshot.wallet,{coins:0,net:0,smoke:0});assert.equal(snapshot.paymentHold,false);assert.equal((await verify(env,a,p)).response.status,409)});
test('concurrent refund replay clamps spent balances, stores deficit and blocks paid economy',async()=>{const {env,sql}=setup(),a=await account(env);await verify(env,a,purchase(a.memberId,'skyline_founder_bundle'));await skylineBilling(request('buy',{item:'net',requestId:'before-refund-buy-001'},a.sessionToken),env);for(let i=0;i<4;i++)await skylineBilling(request('spend',{item:'net',requestId:'before-refund-use-00'+i},a.sessionToken),env);await Promise.all(Array.from({length:4},()=>reconcileRefunds(env,['fixture-token'])));assert.deepEqual(sql.prepare('SELECT coins,net,smoke FROM skyline_wallets').get(),Object.assign(Object.create(null),{coins:0,net:0,smoke:0}));assert.deepEqual(sql.prepare('SELECT coins_debt,net_debt,smoke_debt FROM skyline_refunds').get(),Object.assign(Object.create(null),{coins_debt:200,net_debt:3,smoke_debt:0}));for(const path of ['buy','spend'])assert.equal((await skylineBilling(request(path,{item:'net',requestId:'held-refund-action01'},a.sessionToken),env)).status,409);assert.equal((await verify(env,a,purchase(a.memberId),'brand-new-token')).response.status,409)});
test('unknown token tombstone blocks delayed stale purchased proof',async()=>{const {env,sql}=setup(),a=await account(env);const result=await reconcileRefunds(env,['future-purchase-token']);assert.equal(result.data.unknown,1);assert.equal((await verify(env,a,purchase(a.memberId),'future-purchase-token')).response.status,409);assert.equal(sql.prepare('SELECT count(*) n FROM skyline_purchases_v2').get().n,0)});
