test('reconciliation unauthenticated member keys and disabled sandbox fail closed before Google',async()=>{const {env}=setup(),a=await account(env);env.OWNER_KEY_HASH=Buffer.from(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(ownerKey))).toString('hex');let calls=0;const send=async()=>{calls++;throw Error('must not call Google')};for(const auth of [undefined,a.sessionToken,'incorrect-owner-secret01'])assert.equal((await skylineBilling(request('reconcile',{},auth),env,send)).status,401);env.SKYLINE_PAYMENTS_ENABLED=undefined;assert.equal((await skylineBilling(request('reconcile',{},ownerKey),env,send)).status,503);assert.equal(calls,0)});
