test('mid-refund batch failure rolls back tombstone wallet and entitlement; retry works',async()=>{for(const index of [1,3,5,6]){const state=setup(),a=await account(state.env);await verify(state.env,a,purchase(a.memberId,'skyline_founder_bundle'));state.failBatchAt(index);assert.equal((await reconcileRefunds(state.env,['fixture-token'])).response.status,503);assert.equal(state.sql.prepare('SELECT count(*) n FROM skyline_refunds').get().n,0);assert.equal(state.sql.prepare('SELECT coins FROM skyline_wallets').get().coins,1500);assert.equal((await reconcileRefunds(state.env,['fixture-token'])).data.revoked,1)}});
test('refund arriving during delayed Google verification cannot admit stale grant',async()=>{const {env,sql}=setup(),a=await account(env),p=purchase(a.memberId);let ready;const reached=new Promise(resolve=>ready=resolve);let release;const delayed=new Promise(resolve=>release=resolve);const send=async url=>{if(String(url).includes('oauth2'))return Response.json({access_token:'fixture'});if(String(url).includes('productsv2')){ready();await delayed;return Response.json(p)}return new Response(null,{status:204})};const checking=skylineBilling(request('verify',{productId:'skyline_coins_1500',purchaseToken:'delayed-refund-token'},a.sessionToken),env,send);await reached;await reconcileRefunds(env,['delayed-refund-token']);release();assert.equal((await checking).status,409);assert.equal(sql.prepare('SELECT count(*) n FROM skyline_purchases_v2').get().n,0);assert.equal(sql.prepare('SELECT coins FROM skyline_wallets').get().coins,0)});
