test('local D1 concurrent stale partial snapshots and full refund debit bounded original quantity',{skip:process.env.SKYLINE_TEST_D1!=='1'},async()=>{const {Miniflare}=await import('miniflare');const mf=new Miniflare({modules:true,script:'export default {fetch(){return new Response("local")}}',d1Databases:{DB:'skyline-partial-test'},compatibilityDate:'2026-05-22'});try{const db=await mf.getD1Database('DB');for(const name of ['0003_skyline_billing.sql','0004_skyline_coin_shop.sql','0005_skyline_refunds.sql','0006_skyline_partial_refunds.sql'])for(const statement of readFileSync('drizzle/'+name,'utf8').split(';').map(s=>s.replace(/^--.*$/gm,'').trim()).filter(Boolean))await db.prepare(statement).run();const env={DB:db,SKYLINE_PAYMENTS_ENABLED:'sandbox',GOOGLE_PLAY_SERVICE_ACCOUNT_EMAIL:'test@example.invalid',GOOGLE_PLAY_SERVICE_ACCOUNT_PRIVATE_KEY:pem},a=await account(env);await verify(env,a,quantityPurchase(a.memberId,10));const at=Date.now()-1000;const results=await Promise.all([reconcileRefunds(env,['fixture-token'],{partial:2,remaining:8,at}),reconcileRefunds(env,['fixture-token'],{partial:3,remaining:5,at:at+1}),reconcileRefunds(env,['fixture-token'],{partial:2,remaining:8,at})]);assert.ok(results.every(r=>r.response.status===200));assert.equal((await db.prepare('SELECT coins FROM skyline_wallets').first()).coins,7500);await Promise.all([reconcileRefunds(env,['fixture-token']),reconcileRefunds(env,['fixture-token'],{partial:3,remaining:5,at:at+1})]);assert.equal((await db.prepare('SELECT coins FROM skyline_wallets').first()).coins,0);const record=await db.prepare('SELECT refunded_quantity,coins_debt FROM skyline_refunds').first();assert.equal(record.refunded_quantity,10);assert.equal(record.coins_debt,0);assert.equal((await db.prepare('SELECT count(*) n FROM skyline_payment_holds').first()).n,0)}finally{await mf.dispose()}});
test('partial refund while native settlement awaits cannot overwrite refund settlement watermark',async()=>{const {env,sql}=setup(),a=await account(env),p=quantityPurchase(a.memberId,2);let entered,release;const reached=new Promise(resolve=>entered=resolve),pause=new Promise(resolve=>release=resolve);const send=async url=>{if(String(url).includes('oauth2'))return Response.json({access_token:'fixture'});if(String(url).includes('productsv2'))return Response.json(p);entered();await pause;return new Response(null,{status:204})};const checking=skylineBilling(request('verify',{productId:'skyline_coins_1500',purchaseToken:'fixture-token'},a.sessionToken),env,send);await reached;await reconcileRefunds(env,['fixture-token'],{partial:1,remaining:1});release();assert.equal((await checking).status,409);assert.equal(sql.prepare('SELECT settlement FROM skyline_purchases_v2').get().settlement,'partially_refunded');assert.equal(sql.prepare('SELECT coins FROM skyline_wallets').get().coins,1500)});
test('purchase admitted between unknown refund lookup and transaction cannot escape revocation',async()=>{for(const partial of [undefined,1]){const {env,sql}=setup(),a=await account(env);let entered,release;const reached=new Promise(resolve=>entered=resolve),pause=new Promise(resolve=>release=resolve),basePrepare=env.DB.prepare.bind(env.DB);let paused=false;env.DB.prepare=q=>{const statement=basePrepare(q);if(q==='SELECT member,product,quantity FROM skyline_purchases_v2 WHERE token_hash=?'&&!paused){const original=statement.first.bind(statement);statement.first=async()=>{const result=await original();paused=true;entered();await pause;return result}}return statement};const refund=reconcileRefunds(env,['fixture-token'],{partial});await reached;assert.equal((await verify(env,a,quantityPurchase(a.memberId,2))).response.status,200);release();assert.equal((await refund).response.status,200);assert.equal(sql.prepare('SELECT coins FROM skyline_wallets').get().coins,0);assert.equal(sql.prepare('SELECT settlement FROM skyline_purchases_v2').get().settlement,'revoked');assert.equal(sql.prepare('SELECT count(*) n FROM skyline_payment_holds').get().n,partial?1:0)}});

