test('owner deletion queue is read-only and rejects member credentials',async()=>{const {env,sql}=setup(),a=await account(env);await skylineBilling(request('deletion-request',{},a.sessionToken),env);env.OWNER_KEY_HASH=Buffer.from(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(ownerKey))).toString('hex');for(const auth of [undefined,a.sessionToken,'incorrect-owner-secret01'])assert.equal((await skylineBilling(request('deletion-requests',undefined,auth),env)).status,401);const response=await skylineBilling(request('deletion-requests',undefined,ownerKey),env);assert.equal(response.status,200);const data=await response.json();assert.equal(data.requests.length,1);assert.equal(data.requests[0].member,a.memberId);assert.equal(data.next,null);assert.equal(JSON.stringify(data).includes(a.sessionToken),false);assert.equal(JSON.stringify(data).includes(a.recoveryToken),false);assert.equal(sql.prepare('SELECT status FROM skyline_deletion_requests').get().status,'pending');});
test('owner deletion queue pagination is bounded and rejects malformed cursors',async()=>{const {env,sql}=setup(),a=await account(env);env.OWNER_KEY_HASH=Buffer.from(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(ownerKey))).toString('hex');for(let i=0;i<102;i++){const member='fixture-member-'+i,id='00000000-0000-4000-8000-'+String(i).padStart(12,'0');sql.prepare('INSERT INTO skyline_members VALUES(?,?,?,?)').run(member,'session-'+i,'recovery-'+i,1);sql.prepare('INSERT INTO skyline_deletion_requests VALUES(?,?,?,?)').run(member,id,1,'pending');}const first=await(await skylineBilling(request('deletion-requests',undefined,ownerKey),env)).json();assert.equal(first.requests.length,100);assert.ok(first.next);const second=await(await skylineBilling(request('deletion-requests?after='+first.next,undefined,ownerKey),env)).json();assert.equal(second.requests.length,2);assert.equal(second.next,null);for(const suffix of ['?after=bad','?member='+a.memberId,'?after=&after='])assert.equal((await skylineBilling(request('deletion-requests'+suffix,undefined,ownerKey),env)).status,400);});
