 for(const body of [{},{memberId:a.memberId,recoveryToken:b.recoveryToken},{memberId:a.memberId,recoveryToken:a.recoveryToken,target:b.memberId}])assert.equal((await skylineBilling(request('deletion-request/recovery',body),env)).status,401);
 assert.equal(sql.prepare('SELECT count(*) n FROM skyline_deletion_requests').get().n,0);
