async function deletionOwner(env){env.OWNER_KEY_HASH=Buffer.from(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(ownerKey))).toString('hex');env.SKYLINE_DELETION_PROCESSING_ENABLED='true';}
async function queuedDeletion(env,a){return (await(await skylineBilling(request('deletion-request',{},a.sessionToken),env)).json()).requestId;}
function completeDeletion(env,id,key=ownerKey,extra={}){return skylineBilling(request('deletion-requests/complete',{requestId:id,confirmation:'delete-account',...extra},key),env);}
test('deletion completion requires owner, explicit confirmation, pending request and processing gate',async()=>{
 const {env,sql}=setup(),a=await account(env);await deletionOwner(env);const id=await queuedDeletion(env,a);
 for(const key of [null,a.sessionToken,'incorrect-owner-secret01'])assert.equal((await completeDeletion(env,id,key)).status,401);
 env.SKYLINE_DELETION_PROCESSING_ENABLED=undefined;assert.equal((await completeDeletion(env,id)).status,503);env.SKYLINE_DELETION_PROCESSING_ENABLED='true';
 for(const extra of [{confirmation:'yes'},{memberId:a.memberId},{requestId:'bad'}])assert.equal((await completeDeletion(env,id,ownerKey,extra)).status,400);
 assert.equal((await completeDeletion(env,crypto.randomUUID())).status,404);assert.equal(sql.prepare('SELECT count(*) n FROM skyline_members').get().n,1);
});
test('deletion completion removes all linked billing data and invalidates credentials; retries preserve receipt',async()=>{
 const {env,sql}=setup(),a=await account(env),b=await account(env);await deletionOwner(env);
 await verify(env,a,purchase(a.memberId,'skyline_founder_bundle'),'deleted-player-token');await verify(env,b,purchase(b.memberId),'other-player-token');
 await skylineBilling(request('buy',{item:'smoke',requestId:'delete-test-buy-0001'},a.sessionToken),env);
 await skylineBilling(request('spend',{item:'net',requestId:'delete-test-use-0001'},a.sessionToken),env);
 const token=sql.prepare('SELECT token_hash FROM skyline_purchases_v2 WHERE member=?').get(a.memberId).token_hash;
 sql.prepare('INSERT INTO skyline_refunds(token_hash,voided_at) VALUES(?,?)').run(token,1);
 sql.prepare('INSERT INTO skyline_refund_events VALUES(?,?,?,?)').run('event-fixture',token,1,null);
 sql.prepare('INSERT INTO skyline_payment_holds VALUES(?,?,?)').run(a.memberId,'fixture',1);
 const bBefore=await(await skylineBilling(request('entitlements',undefined,b.sessionToken),env)).json();const id=await queuedDeletion(env,a);
 const first=await completeDeletion(env,id);assert.equal(first.status,200);const receipt=await first.json();assert.equal(receipt.status,'completed');
 assert.deepEqual(await(await completeDeletion(env,id)).json(),receipt);
 for(const table of ['skyline_wallets','skyline_purchases_v2','skyline_entitlements','skyline_spends_v2','skyline_coin_buys_v2','skyline_payment_holds','skyline_deletion_requests'])assert.equal(sql.prepare('SELECT count(*) n FROM '+table+' WHERE member=?').get(a.memberId).n,0,table);
 assert.equal(sql.prepare('SELECT count(*) n FROM skyline_members WHERE id=?').get(a.memberId).n,0);
 for(const table of ['skyline_refunds','skyline_refund_events'])assert.equal(sql.prepare('SELECT count(*) n FROM '+table+' WHERE token_hash=?').get(token).n,0);
 assert.equal((await skylineBilling(request('entitlements',undefined,a.sessionToken),env)).status,401);
 assert.equal((await skylineBilling(request('recover',{memberId:a.memberId,recoveryToken:a.recoveryToken}),env)).status,401);
 assert.equal((await skylineBilling(request('deletion-request/recovery',{memberId:a.memberId,recoveryToken:a.recoveryToken}),env)).status,401);
 assert.deepEqual(await(await skylineBilling(request('entitlements',undefined,b.sessionToken),env)).json(),bBefore);
 const saved=sql.prepare('SELECT * FROM skyline_deletion_completions').get();assert.deepEqual(Object.keys(saved),['request_hash','completed']);assert.notEqual(saved.request_hash,id);assert.equal(JSON.stringify(saved).includes(a.memberId),false);
 assert.equal((await(await skylineBilling(request('deletion-requests',undefined,ownerKey),env)).json()).requests.length,0);
});
