test('local D1 completes concurrent deletion retries atomically and preserves another member',{skip:process.env.SKYLINE_TEST_D1!=='1'},async()=>{
 const {Miniflare}=await import('miniflare');const mf=new Miniflare({modules:true,script:'export default {fetch(){return new Response("local")}}',d1Databases:{DB:'skyline-local-delete-test'},compatibilityDate:'2026-05-22'});
 try{
  const db=await mf.getD1Database('DB');
  for(const name of ['0003_skyline_billing.sql','0004_skyline_coin_shop.sql','0005_skyline_refunds.sql','0006_skyline_partial_refunds.sql','0008_skyline_deletion_requests.sql','0009_skyline_deletion_completion.sql','0010_skyline_deletion_health.sql'])for(const statement of readFileSync('drizzle/'+name,'utf8').split(';').map(s=>s.replace(/^--.*$/gm,'').trim()).filter(Boolean))await db.prepare(statement).run();
  const env={DB:db,SKYLINE_PAYMENTS_ENABLED:'sandbox',GOOGLE_PLAY_SERVICE_ACCOUNT_EMAIL:'test@example.invalid',GOOGLE_PLAY_SERVICE_ACCOUNT_PRIVATE_KEY:pem};await deletionOwner(env);const a=await account(env),b=await account(env);await verify(env,a,purchase(a.memberId,'skyline_founder_bundle'));const id=await queuedDeletion(env,a);
  const results=await Promise.all(Array.from({length:3},async()=>{const r=await completeDeletion(env,id);assert.equal(r.status,200);return r.json();}));assert.equal(new Set(results.map(r=>r.completedAt)).size,1);
  assert.equal((await db.prepare('SELECT count(*) n FROM skyline_members').first()).n,1);assert.equal((await db.prepare('SELECT count(*) n FROM skyline_purchases_v2').first()).n,0);assert.equal((await skylineBilling(request('entitlements',undefined,a.sessionToken),env)).status,401);assert.equal((await skylineBilling(request('entitlements',undefined,b.sessionToken),env)).status,200);
  const expiry=Date.now();await db.prepare('UPDATE skyline_deletion_completions SET completed=?').bind(expiry-30*86400000).run();
  const cleaned=await skylineDeletionMaintenance(env,expiry);assert.equal(cleaned.purgedReceipts,1);assert.equal((await db.prepare('SELECT count(*) n FROM skyline_deletion_completions').first()).n,0);assert.equal((await completeDeletion(env,id)).status,404);
 }finally{await mf.dispose();}
});

