 sql.prepare('INSERT INTO skyline_deletion_completions VALUES(?,?)').run('expired-fixture',1);
 for(const key of [null,a.sessionToken,'incorrect-owner-secret01'])assert.equal((await skylineBilling(request('deletion-maintenance',{},key),env)).status,401);
 assert.equal((await skylineBilling(request('deletion-maintenance',{now:Date.now()+365*86400000},ownerKey),env)).status,400);
 env.SKYLINE_DELETION_PROCESSING_ENABLED=undefined;assert.equal((await skylineBilling(request('deletion-maintenance',{},ownerKey),env)).status,503);assert.equal(sql.prepare('SELECT count(*) n FROM skyline_deletion_completions').get().n,1);
 env.SKYLINE_DELETION_PROCESSING_ENABLED='true';const r=await skylineBilling(request('deletion-maintenance',{},ownerKey),env);assert.equal(r.status,200);assert.equal((await r.json()).purgedReceipts,1);
