test('owner queue exposes seven-day deadline and maintenance reports exact overdue boundary',async()=>{
 const {env,sql}=setup(),a=await account(env),b=await account(env);await deletionOwner(env);await queuedDeletion(env,a);await queuedDeletion(env,b);const now=Date.now();
 sql.prepare('UPDATE skyline_deletion_requests SET requested=? WHERE member=?').run(now-7*86400000,a.memberId);sql.prepare('UPDATE skyline_deletion_requests SET requested=? WHERE member=?').run(now-7*86400000+1,b.memberId);
 const queue=await(await skylineBilling(request('deletion-requests',undefined,ownerKey),env)).json();assert.equal(queue.requests.find(r=>r.member===a.memberId).deadlineAt,now);
 const report=await skylineDeletionMaintenance(env,now);assert.equal(report.pending,2);assert.equal(report.overdue,1);assert.equal(report.nextDeadline,now);
 assert.equal(sql.prepare('SELECT count(*) n FROM skyline_members').get().n,2,'maintenance never completes deletion without an owner completion action');
 assert.equal(JSON.stringify(report).includes(a.memberId),false);
});

test('owner health is read-only, rejects visitor access, and distinguishes manual cleanup from a scheduled invocation',async()=>{
 const {env,sql}=setup(),a=await account(env);await deletionOwner(env);await queuedDeletion(env,a);
 const counts=()=>({members:sql.prepare('SELECT count(*) n FROM skyline_members').get().n,receipts:sql.prepare('SELECT count(*) n FROM skyline_deletion_completions').get().n});
 const before=counts();
 for(const key of [null,a.sessionToken,'incorrect-owner-secret01'])assert.equal((await skylineBilling(request('deletion-health',undefined,key),env)).status,401);
 env.SKYLINE_DELETION_PROCESSING_ENABLED=undefined;
 const fresh=await(await skylineBilling(request('deletion-health',undefined,ownerKey),env)).json();
 assert.equal(fresh.processingEnabled,false);assert.equal(fresh.pending,1);assert.equal(fresh.lastMaintenanceAt,null);assert.equal(fresh.scheduledRecently,false);
 assert.deepEqual(counts(),before);assert.equal(JSON.stringify(fresh).includes(a.memberId),false);
 assert.equal((await skylineBilling(request('deletion-health?now=1',undefined,ownerKey),env)).status,400);
 env.SKYLINE_DELETION_PROCESSING_ENABLED='true';const now=Date.now();
 await skylineDeletionMaintenance(env,now);
 const manual=await(await skylineBilling(request('deletion-health',undefined,ownerKey),env)).json();assert.equal(manual.lastMaintenanceAt,now);assert.equal(manual.lastScheduledAt,null);assert.equal(manual.scheduledRecently,false);
 await skylineDeletionMaintenance(env,now,'scheduled');
 const scheduled=await(await skylineBilling(request('deletion-health',undefined,ownerKey),env)).json();assert.equal(scheduled.lastScheduledAt,now);assert.equal(scheduled.scheduledRecently,true);
 await skylineDeletionMaintenance(env,now+1);assert.equal(sql.prepare('SELECT last_scheduled FROM skyline_deletion_health').get().last_scheduled,now,'manual runs cannot refresh the scheduled heartbeat');
 sql.prepare('UPDATE skyline_deletion_health SET last_scheduled=?').run(Date.now()-2*3600000);
 assert.equal((await(await skylineBilling(request('deletion-health',undefined,ownerKey),env)).json()).scheduledRecently,false);
});
test('failed maintenance cannot purge a receipt or write a success heartbeat',async()=>{
 for(const stage of [0,1]){
  const {env,sql,failBatchAt}=setup();await deletionOwner(env);sql.prepare('INSERT INTO skyline_deletion_completions VALUES(?,?)').run('expired-fixture',1);
  failBatchAt(stage);await assert.rejects(()=>skylineDeletionMaintenance(env,Date.now(),'scheduled'));
  assert.equal(sql.prepare('SELECT count(*) n FROM skyline_deletion_completions').get().n,1);
  assert.equal(sql.prepare('SELECT count(*) n FROM skyline_deletion_health').get().n,0);
 }
});

function productionEnv(env){return {...env,SKYLINE_BILLING_ENVIRONMENT:'production',SKYLINE_PAYMENTS_ENABLED:'production'}}
function realPurchase(member,quantity=1,product='skyline_coins_1500'){const p=quantityPurchase(member,quantity,product);delete p.testPurchaseContext;return p}

test('unknown environment and mismatched payment mode fail closed before database or Google',async()=>{
 for(const [environment,payments] of [['invalid',undefined],['',undefined],['production','sandbox'],['sandbox','production'],[undefined,'true'],['production','true']]){
  let touched=0;const env={DB:{prepare(){touched++;throw Error('database must remain untouched')}},SKYLINE_BILLING_ENVIRONMENT:environment,SKYLINE_PAYMENTS_ENABLED:payments};
  for(const path of ['account','entitlements','deletion-request','reconcile'])assert.equal((await skylineBilling(request(path,path==='entitlements'?undefined:{}),env,async()=>{touched++;throw Error('Google must remain untouched')})).status,503);
  assert.equal(touched,0);
 }
});
test('production never falls back when production migration is absent',async()=>{
 const {env,sql}=setup();sql.exec('DROP TABLE skyline_production_members');assert.equal((await skylineBilling(request('account',{}),productionEnv(env))).status,503);assert.equal(sql.prepare('SELECT count(*) n FROM skyline_members').get().n,0);
});
test('production rejects present test context including null or malformed contexts and invalid proof',async()=>{
 for(const mutate of [p=>p.testPurchaseContext={fopType:'TEST'},p=>p.testPurchaseContext=null,p=>p.testPurchaseContext={},p=>p.testPurchaseContext='TEST',p=>p.obfuscatedExternalAccountId='wrong',p=>p.productLineItem[0].productOfferDetails.refundableQuantity=0,p=>p.productLineItem.push(p.productLineItem[0])]){
  const {env:base,sql}=setup(),env=productionEnv(base),a=await account(env),p=realPurchase(a.memberId);mutate(p);assert.notEqual((await verify(env,a,p)).response.status,200);assert.equal(sql.prepare('SELECT coins FROM skyline_production_wallets').get().coins,0);
 }
});
test('production pending cancelled and already consumed unknown receipts grant nothing',async()=>{
 for(const state of ['PENDING','CANCELLED','CONSUMED']){const {env:base,sql}=setup(),env=productionEnv(base),a=await account(env),p=realPurchase(a.memberId);
  if(state==='CONSUMED')p.productLineItem[0].productOfferDetails.consumptionState='CONSUMPTION_STATE_CONSUMED';else p.purchaseStateContext.purchaseState=state;
  assert.equal((await verify(env,a,p)).response.status,state==='PENDING'?200:409);assert.equal(sql.prepare('SELECT coins FROM skyline_production_wallets').get().coins,0);
 }
});
test('production settlement retry and concurrent grants are idempotent; paid economy remains isolated',async()=>{
 const {env:base,sql}=setup(),env=productionEnv(base),a=await account(env),p=realPurchase(a.memberId);
 assert.equal((await verify(env,a,p,'production-retry-token',true)).data.settlement,'retry');const retries=await Promise.all(Array.from({length:3},()=>verify(env,a,p,'production-retry-token')));assert.ok(retries.every(r=>r.data.settlement==='complete'));
 assert.equal(sql.prepare('SELECT coins FROM skyline_production_wallets').get().coins,1500);assert.equal(sql.prepare('SELECT count(*) n FROM skyline_production_purchases_v2').get().n,1);
 for(const path of ['buy','spend'])for(let i=0;i<2;i++)assert.equal((await skylineBilling(request(path,{item:'net',requestId:'production-fixed-'+path},a.sessionToken),env)).status,200);
 const wallet=sql.prepare('SELECT coins,net FROM skyline_production_wallets').get();assert.equal(wallet.coins,1300);assert.equal(wallet.net,0);
 for(const table of ['members','wallets','purchases_v2','coin_buys_v2','spends_v2'])assert.equal(sql.prepare('SELECT count(*) n FROM skyline_'+table).get().n,0);
});
